{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Metoclopramide, a P-gp substrate with a basic amine, exhibits good passive BBB permeability and appreciable brain distribution despite functional P-gp efflux, showing that efflux liability alone does not preclude meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Urolithin B, a fused tricyclic oxygen heterocycle, was detected in rat brain after intravenous administration, supporting CNS access for the related fused heteroaromatic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Fenbendazole, a larger heteroaromatic compound, was detected in CSF within 10 minutes via passive diffusion and is not a P-gp substrate, supporting rapid CNS access for similar aromatic/heteroaromatic structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Paeonol reached 202.86 ng/g in rat brain after systemic administration, demonstrating measurable brain penetration despite rapid clearance.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Remacemide was detected in human and canine cerebrospinal fluid, supporting CNS access for lipophilic amine-containing molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer experimental analogues demonstrate BBB/CSF penetration, including a P-gp substrate with good brain distribution; therefore the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for the query itself.",
    "Magnitude of P-gp efflux for the cationic xanthene query is not directly quantified.",
    "Brain-to-plasma exposure ratio for the query remains uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

